import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "एच पी एल सी जांच में थैलेसीमिया कैरियर निकला? और अब डॉक्टर ने म्यूटेशन एनालिसिस करवाने को कहा है? यह क्या है, और क्यों ज़रूरी है, आखिर तक देखिए.",
 "हमारे खून के हीमोग्लोबिन में, बीटा ग्लोबिन नाम का प्रोटीन होता है. इसका नुस्खा एच बी बी जीन में है, जो क्रोमोसोम ग्यारह पर होता है. इस जीन में गड़बड़ी को, म्यूटेशन कहते हैं.",
 "एच पी एल सी जांच बताती है, कि आप कैरियर हैं या नहीं. लेकिन म्यूटेशन एनालिसिस बताता है, कि जीन में ठीक कौन सी गड़बड़ी है. यह डी एन ए की जांच है, जो खून के सैंपल से होती है.",
 "भारत में कई तरह के म्यूटेशन मिले हैं, पर कुछ बहुत आम हैं. पश्चिम बंगाल के एक अस्पताल अध्ययन में, कैरियर्स में सबसे आम था, आई वी एस वन फाइव, लगभग सैंतालीस प्रतिशत. इसके बाद कोडॉन छब्बीस, यानी एच बी ई.",
 "जांच कैसे होती है? पहले आम म्यूटेशन, ए आर एम एस पी सी आर से देखे जाते हैं. ज़रूरत हो, तो पूरे जीन को, सैंगर सीक्वेंसिंग से अक्षर अक्षर पढ़ा जाता है. और जीन के टुकड़े गायब होने, यानी डिलीशन, के लिए अलग जांच होती है.",
 "यह क्यों ज़रूरी है? अगर पति और पत्नी दोनों कैरियर हों, तो हर प्रेगनेंसी में बच्चे को थैलेसीमिया मेजर होने की संभावना, चार में से एक होती है. और प्रेगनेंसी में बच्चे की जांच तभी हो सकती है, जब माता पिता, दोनों के म्यूटेशन पहले से पता हों.",
 "प्रेगनेंसी में, आमतौर पर दस से तेरह हफ्ते के बीच, सी वी एस जांच से बच्चे का सैंपल लिया जाता है, और उसमें वही म्यूटेशन देखे जाते हैं. यह जांच सिर्फ बीमारी के लिए होती है. बच्चे का लिंग कभी नहीं बताया जाता.",
 "मरीज़ में, म्यूटेशन से बीमारी की गंभीरता का अंदाज़ा मिलता है. कुछ म्यूटेशन में बीटा ग्लोबिन बिल्कुल नहीं बनता, कुछ में थोड़ा बनता है. एच बी ई के साथ बीटा थैलेसीमिया, अक्सर बीच वाले रूप जैसा होता है. पर इलाज का फैसला, सिर्फ डॉक्टर करते हैं.",
 "यह जांच किसके लिए है? कैरियर पति पत्नी, प्रेगनेंसी की योजना से पहले. जिनके परिवार में थैलेसीमिया मेजर का बच्चा हो. जिनकी रिपोर्ट साफ नहीं, जैसे बॉर्डरलाइन एच बी ए टू. और थैलेसीमिया के मरीज़. रिपोर्ट को जेनेटिक काउंसलर से ज़रूर समझें.",
 close_voice("क्या आपने और आपके जीवनसाथी ने थैलेसीमिया जांच करवाई है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/btmr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/btm_{i}.wav"],check=True); f=f"/tmp/btm_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/btm_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
